const body = $input.first().json.body;
const campos = body.campos || {};
const out = { id: body.evento_id };
for (const key of Object.keys(campos)) {
    if (key === 'quando') {
          out.quando = DateTime.fromISO(campos.quando, { zone: 'Europe/Lisbon' }).toISO();
    } else {
          out[key] = campos[key];
    }
}
return [{ json: out }];

// Duplicados para o formulario "Nova lead" do Terminal: so o que o comercial precisa
// para decidir (nome, fase, de quem e). Nada de telefones nem emails de volta.
const recs = ($input.first().json.records) || [];
return [{ json: { ok: true, duplicados: recs.map(r => {
  const f = r.fields || {};
  return { id: r.id, nome: f.Nome || '?', estagio: f.estagio || 'lead', comercial_id: Array.isArray(f.Comercial) ? f.Comercial[0] : null };
}) } }];
